          "id": "ch3_marxism_sec_9",
          "title": "Core Tenets of Marxism",
          "start_page": 20,
          "paragraphs": [
            {
              "page": 20,
              "text": "Marxism is grounded in a critical analysis of capitalism, focusing on how material conditions and class relations shape social development. Its foundational pillars are historical materialism and class struggle , leading ultimately to a vision of a classless, communist society . 1. Historical Materialism Marxism begins with the premise that economic structures drive historical change . The material mode of production—how goods are produced and distributed—determines social, legal, and political institutions. \"The history of all hitherto existing society is the history of class struggles.\" – Karl Marx 2. Class Struggle: The Engine of History a. Structural Division Every historical epoch is defined by the division between those who own the means of production and those who labor . In capitalism, this manifests as:"
            },
            {
              "page": 21,
              "text": "Marxists argue that the state serves the ruling class by maintaining economic dominance through legal, political, and ideological tools. \"The executive of the modern state is but a committee for managing the common affairs of the whole bourgeoisie.\" – Karl Marx Example : Corporate lobbying influencing public policy in democracies reflects the merging of economic and political power. 3. Class Consciousness and Social Change Marxism posits that revolutionary change emerges when the proletariat becomes conscious of its exploitation and unites for collective action—manifested in strikes, revolts , or revolutions . Examples include the civil rights movement or anti-apartheid struggle , which, while not purely economic, reflect systemic responses to structural domination. 4. Transition to Communism Marx envisions a proletarian revolution as the catalyst for transforming society. With the abolition of private property , the working class would control production, leading to a classless and stateless society based on collective ownership and economic equality . \"In place of the old bourgeois society... we shall have an association in which the free development of each is the condition for the free development of all.\" – Karl Marx Dialectical Materialism: The Philosophical Core of Marxism Dialectical Materialism fuses dialectics (change through contradiction) with materialism (primacy of material conditions). It serves as the methodological foundation of Marxist theory."
            }
          ],
