              "full_text": "Purpose : Use the state as an instrument to dismantle bourgeois control , prevent counter-revolution , and initiate socialist transformation . \"The history of all hitherto existing society is the history of class struggles.\" – Karl Marx \"Political power is merely the organized power of one class for oppressing another.\" – Friedrich Engels"
