              "full_text": "Role of the State : Temporarily centralizes authority under proletarian control to protect revolutionary gains , until the state itself becomes unnecessary and withers away. \"Democracy for the rich – that is the democracy of capitalist society.\" – Vladimir Lenin \"The state is nothing but an instrument of oppression of one class by another.\" – Friedrich Engels"
