          "id": "ch3_marxism_sec_13",
          "title": "Marxist Internationalism: Core Ideas and Contemporary Relevance",
          "start_page": 27,
          "paragraphs": [
            {
              "page": 27,
              "text": "Global Working-Class Solidarity Marxism envisions the working class as a global force united by shared exploitation under capitalism. The slogan \"Workers of the world, unite!\" captures the essence of this solidarity beyond national boundaries. Common Class Interests Across nations, the proletariat confronts similar challenges—low wages, poor working conditions, and social inequality. Marxists argue that class interests override national divisions. “The capitalists of the world and their governments are prepared to commit any crime to defend the interests of the capitalist system.” – Vladimir Lenin Anti-Imperialism Marxism critiques imperialism as a tool of capitalist expansion, where dominant nations exploit weaker ones economically and politically. It champions the liberation of colonized and oppressed peoples. “Freedom is always and exclusively freedom for the one who thinks differently.” – Rosa Luxemburg International Revolution Marxists advocate for a coordinated global revolution, where workers collectively dismantle capitalist structures to establish socialism worldwide. “The historic ascent of humanity... may be summarized as a succession of victories of consciousness over blind forces.” – Leon Trotsky Contemporary Relevance Though global revolution remains aspirational, Marxist internationalism continues to inspire transnational movements against inequality, corporate power, and neocolonialism. “In solidarity, we find our strength... to build a more just and equitable world for all.” Marx’s Analysis of the State 1. Instrument of Class Domination Marx viewed the state as a tool of the ruling class to maintain control. Under capitalism, it functions to uphold bourgeois interests by protecting private property and suppressing dissent. \"The executive of the modern state is but a committee for managing the common affairs of the whole bourgeoisie.\" – Karl Marx"
            },
            {
              "page": 28,
              "text": "2. Reflection of Economic Base Rooted in historical materialism , Marx argued that the economic base (mode of production and class relations) determines the superstructure , including the state. \"It is not the consciousness of men that determines their existence, but their social existence that determines their consciousness.\" – Karl Marx 3. State as Superstructure The state is not neutral; it reflects the dominant class's interests as shaped by underlying economic forces. \"The state, in relation to civil society, is just as much a presupposition as civil society is in relation to the state.\" – Karl Marx 4. Dictatorship of the Bourgeoisie In capitalism, the state represents bourgeois rule. Its institutions—government, judiciary, military—enforce class dominance. Repeated Quote: \"The executive of the modern state...\" – Karl Marx 5. Arena of Class Struggle Though dominated by the bourgeoisie, the state becomes a site of class contestation. The working class can exert pressure for reforms. \"The state is nothing but an instrument of oppression of one class by another – no less so in a democratic republic than in a monarchy.\" – Friedrich Engels 6. Withering Away of the State In communism, with class antagonisms abolished and collective ownership established, Marx predicted the state would become obsolete and \"wither away.\" Marx’s Concept of Freedom Marx’s notion of freedom transcends mere non-interference (negative freedom), emphasizing positive freedom—the real capacity to lead a fulfilling, self-directed life. His idea is inseparable from critiques of capitalism , where exploitation, alienation, and class hierarchies obstruct true human freedom."
            }
          ],
