          "id": "ch3_marxism_sec_19",
          "title": "Neo-Marxism: Expanding Classical Marxism",
          "start_page": 32,
          "paragraphs": [
            {
              "page": 32,
              "text": "1. Broadening Marxist Analysis Neo-Marxism extends classical Marxism by incorporating culture, identity, ideology , and non-class oppressions , responding to the complexities of late capitalism and modern societies. 2. Culture and Ideology as Tools of Domination Neo-Marxists emphasize how culture and mass media propagate dominant ideologies, manufacturing consent and reinforcing capitalist norms. \"Culture today is infecting everything with sameness.\" – Theodor Adorno"
            },
            {
              "page": 33,
              "text": "Example: Adorno & Horkheimer's Dialectic of Enlightenment critiques the culture industry for promoting conformity and commodification . 3. Intersectionality and Multi-Dimensional Oppression Neo-Marxism recognizes that power operates not only through class, but also race, gender, and culture —often in intersecting ways. \"Intersectionality is not about identity; it's about power.\" – Kimberlé Crenshaw 4. Critique of Capitalism’s Cultural Logic Neo-Marxists like Herbert Marcuse argue that capitalism manufactures passive, consumerist citizens through cultural saturation. \"A comfortable, smooth, reasonable, democratic unfreedom prevails in advanced industrial civilization.\" – Marcuse Example: One-Dimensional Man critiques the ideological pacification of individuals in consumer societies. 5. Social Movements and Resistance Neo-Marxism studies grassroots resistance and counter-hegemonic struggles , particularly in civil society. \"The old world is dying, and the new world struggles to be born: now is the time of monsters.\" – Antonio Gramsci 6. Postcolonial and Global Dimensions Many Neo-Marxists analyze imperialism, colonialism , and global inequalities as integral to capitalist domination. \"Imperialism leaves behind germs of rot...\" – Frantz Fanon Example: Fanon's The Wretched of the Earth ties colonial oppression to class struggle. 7. Diverse Theoretical Streams Neo-Marxism is not a single doctrine but a family of approaches:"
            }
          ],
