          "id": "ch3_marxism_sec_21",
          "title": "Continued Relevance of Neo-Marxism",
          "start_page": 35,
          "paragraphs": [
            {
              "page": 35,
              "text": "1. Globalization and Inequality Neo-Marxism critiques how global capitalism —driven by multinational corporations and global finance— deepens inequality within and between nations. Example: Exploitation in Asian sweatshops linked to Western consumer markets reveals global class structures. 2. Critique of Consumer Culture Neo-Marxists examine consumerism and commodification as tools of ideological control, building on Marx’s idea of commodity fetishism . \"Free election of masters does not abolish the masters or the slaves.\" – Herbert Marcuse Example: Advertising manufactures artificial needs, perpetuating capitalist values and cultural conformity. 3. Identity and Intersectionality Neo-Marxism integrates race, gender, sexuality with class, analyzing how multiple systems of oppression intersect. \"Intersectionality is not about identity; it's about power.\" – Kimberlé Crenshaw Example: Class struggles of working-class women of color differ from white middle-class feminism. 4. Surveillance and Digital Capitalism It critiques the rise of surveillance capitalism , where social media, data extraction, and algorithmic control reproduce inequality and corporate dominance."
            }
          ],
